import java.io.IOException;
import java.sql.*;
import javax.sql.DataSource;
import jakarta.servlet.http.*;

public class UserLookupServlet extends HttpServlet {
    private DataSource dataSource;

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws IOException {
        String username = request.getParameter("username");

        // Use a parameterized query so input is treated as data, not executable SQL.
        String sql = "SELECT id FROM users WHERE username = ?";

        try (Connection connection = dataSource.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setString(1, username);

            try (ResultSet results = statement.executeQuery()) {
                response.getWriter().println(
                        results.next() ? "User found" : "User not found"
                );
            }
        } catch (SQLException e) {
            // Log the exception server-side without exposing database details.
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
        }
    }
}
