{
  "startup_name": "Tipperary",
  "tagline": "Know before you tip.",
  "elevator_pitch": "Tipperary is a restaurant discovery app that shows the average tip size at each restaurant, helping diners understand local tipping norms and make confident, informed decisions. By combining anonymized transaction data with verified user contributions, Tipperary brings transparency to an often confusing part of dining out.",
  "problem": {
    "summary": "Tipping expectations vary widely by restaurant, location, service type, and occasion.",
    "pain_points": [
      "Diners are unsure whether their tip is appropriate.",
      "Travelers may not understand local tipping customs.",
      "Restaurant reviews rarely provide reliable tipping insights.",
      "Hospitality businesses lack clear benchmarks for guest tipping behavior."
    ]
  },
  "solution": {
    "summary": "Tipperary provides restaurant-level tipping benchmarks through a simple, searchable mobile experience.",
    "core_features": [
      {
        "name": "Average Tip by Restaurant",
        "description": "View the typical tip as a percentage and monetary amount."
      },
      {
        "name": "Contextual Benchmarks",
        "description": "Compare tipping patterns by neighborhood, cuisine, service type, and price range."
      },
      {
        "name": "Anonymous Tip Sharing",
        "description": "Contribute receipt or transaction data without exposing personal financial information."
      },
      {
        "name": "Confidence Indicators",
        "description": "See sample size, data freshness, and estimated reliability for every average."
      },
      {
        "name": "Personal Tipping Assistant",
        "description": "Calculate a tip based on the bill, local norms, and the diner's preferred service rating."
      }
    ]
  },
  "how_it_works": [
    "The user searches for or selects a restaurant.",
    "Tipperary displays the restaurant's average tip percentage and amount.",
    "The user can filter results by dining period, party size, or service type.",
    "After dining, the user may anonymously submit tip information or upload a receipt.",
    "Tipperary aggregates contributions and updates its benchmarks while filtering outliers and suspicious data."
  ],
  "target_customers": [
    "Frequent restaurant diners",
    "Travelers and tourists",
    "Young adults navigating tipping etiquette",
    "Expense-conscious consumers",
    "Restaurants and hospitality groups seeking market benchmarks"
  ],
  "market_opportunity": {
    "summary": "Millions of restaurant transactions generate tipping data every day, yet diners have no trusted platform for understanding that information.",
    "initial_market": "Urban diners in markets where tipping is common and restaurant spending is high.",
    "expansion_paths": [
      "Hotels, bars, cafés, salons, delivery services, and other tipped industries",
      "International tipping guides",
      "Restaurant analytics and workforce insights"
    ]
  },
  "business_model": [
    {
      "stream": "Consumer Subscription",
      "description": "A premium plan offering personalized tipping insights, travel guides, receipt history, and advanced comparisons."
    },
    {
      "stream": "Restaurant Analytics",
      "description": "Subscription dashboards showing anonymized tipping trends, benchmark comparisons, and service-performance indicators."
    },
    {
      "stream": "Sponsored Discovery",
      "description": "Clearly labeled restaurant promotions and reservation partnerships."
    },
    {
      "stream": "Data Partnerships",
      "description": "Privacy-safe, aggregated market insights for hospitality platforms and industry researchers."
    }
  ],
  "competitive_advantage": [
    "A focused, restaurant-level tipping data set",
    "Transparent sample sizes and confidence ratings",
    "Privacy-first aggregation rather than exposure of individual diners or workers",
    "Network effects: every contribution improves the product",
    "A utility that complements restaurant review, reservation, and payment platforms"
  ],
  "go_to_market": {
    "launch_strategy": [
      "Begin in one restaurant-dense metropolitan area.",
      "Partner with food creators, travel influencers, and hospitality communities.",
      "Offer receipt-based rewards for early contributors.",
      "Publish neighborhood tipping reports to generate media coverage.",
      "Integrate with reservation, expense, and payment platforms."
    ],
    "growth_loop": "Users consult Tipperary before dining, submit data afterward, improve the benchmark, and give future diners a stronger reason to use the app."
  },
  "trust_and_privacy": {
    "principles": [
      "Never publish individual customer or employee tipping records.",
      "Require minimum sample sizes before displaying restaurant-level averages.",
      "Remove identifying information from uploaded receipts.",
      "Detect manipulated submissions and statistical outliers.",
      "Present tipping data as guidance, not as a mandatory expectation.",
      "Avoid using the product to rank or penalize individual service workers."
    ]
  },
  "vision": "Tipperary will become the trusted transparency layer for tipping worldwide, helping consumers navigate social expectations while giving hospitality businesses a clearer view of industry trends.",
  "funding_ask": {
    "stage": "Pre-seed",
    "purpose": [
      "Build the mobile application and data platform",
      "Launch and validate the product in the first market",
      "Develop privacy, verification, and fraud-detection systems",
      "Secure restaurant, payment, and reservation partnerships"
    ]
  },
  "closing_statement": "Restaurant prices are visible, reviews are searchable, and menus are online. Tipping remains uncertain. Tipperary makes it transparent."
}

